response:
{
  "id": "tang-po-imagery",
  "title": "唐诗中的意象",
  "subtitle": "物色与情思的交融",
  "language": "zh-CN",
  "audience": "高中及以上文学爱好者",
  "theme": "vellum",
  "tutor": {
    "suggestions": [
      "为什么'鸡声茅店月'全是名词却画面感极强？",
      "李白的'月'和杜甫的'月'有什么本质不同？",
      "没去过玉门关的诗人为什么也爱写玉门关？",
      "现代人如何跨越时空与唐诗意象共情？"
    ],
    "kb": [
      {
        "pattern": "意象|客观物象",
        "answer": "客观物象与主观情思的融合。非纯然景物，亦非抽象情感，而是'意中之象'，如'明月'不仅是天体，更是思乡的肉身。"
      },
      {
        "pattern": "意境|意境生成",
        "answer": "多个意象组合后生成的整体氛围与审美空间。意象是砖石，意境是殿堂；意象是局部，意境是整体。"
      },
      {
        "pattern": "并置|名词并置",
        "answer": "意象组合技巧之一，省去动词与逻辑连接词，将几个名词直接排列，如'鸡声茅店月'，强迫读者用想象填补空白，产生蒙太奇效果。"
      },
      {
        "pattern": "公共意象|集体无意识",
        "answer": "被整个时代或文化反复使用、具有固定情感指向的意象，如'折柳'表送别、'长亭'表羁旅，承载集体无意识。"
      },
      {
        "pattern": "个人化意象|奇诡意象",
        "answer": "带有诗人强烈个性印记、甚至精神病理特征的意象，如李贺的'鬼雨''恨血'，无法被轻易复制或替代。"
      }
    ]
  },
  "scenes": [
    {
      "id": "cover",
      "kind": "hero",
      "notes": "开场定调：唐诗之美，不在直抒胸臆，而在以物传情。意象是解开唐诗审美密码的钥匙。用沉静的书卷气引入，避免过度煽情。",
      "blocks": [
        {
          "id": "b_cover",
          "type": "hero",
          "intent": "封面：标题+副题",
          "size": "xl"
        }
      ]
    },
    {
      "id": "definition",
      "kind": "content",
      "eyebrow": "审美与文本",
      "headline": "意象：客观物象与主观情思的融合",
      "lead": "意象非纯然景物，亦非抽象情感，而是物色与情思的婚媾。",
      "notes": "讲清意象是'意中之象'，王昌龄《诗格》首提。比喻是A像B，象征是A代表B，意象是A就是B的情感本身。比如'明月'不是像思乡，也不是代号，它就是思乡的肉身。辨析这三者是理解唐诗的基石。",
      "blocks": [
        {
          "id": "b1",
          "type": "list",
          "intent": "厘清意象的定义及其与比喻、象征的核心区别",
          "size": "m"
        },
        {
          "id": "b2",
          "type": "callout",
          "intent": "辨析：比喻重在'比'，象征重在'征'，意象重在'融'",
          "size": "s"
        }
      ]
    },
    {
      "id": "combination",
      "kind": "content",
      "eyebrow": "组合与意境",
      "headline": "意象的组合与意境的生成",
      "lead": "孤立意象仅是词汇，意象叠加方生意境。",
      "transition": "zoom",
      "notes": "全课难点。为什么没有动词却画面感极强？因为并置切断了逻辑链条，强迫读者用想象填补空白，这就是'留白'。'月'与'霜'的冷色叠加，'鸡声'的听觉刺破视觉，通感在此发生。要让学生'看见'意境是如何从字缝里长出来的。",
      "blocks": [
        {
          "id": "b3",
          "type": "statement",
          "intent": "具象锚点：温庭筠'鸡声茅店月，人迹板桥霜'的纯名词并置与蒙太奇效应",
          "size": "l"
        },
        {
          "id": "b4",
          "type": "flow",
          "intent": "展示意象并置→叠加→通感→意境的生成路径",
          "size": "m"
        }
      ]
    },
    {
      "id": "context",
      "kind": "content",
      "eyebrow": "历史与语境",
      "headline": "制度与风物：唐代意象的社会土壤",
      "lead": "意象并非凭空产生，它们深植于唐代的交通、战争与科举制度中。",
      "notes": "长亭与渡口源于驿站制度，大漠烽火源于边塞战争，孤舟与客帆源于科举漫游。玉门关在盛唐已成为一种'文化坐标'，写它不是为了写实，而是为了调用边塞的悲壮语境。揭示意象背后的集体无意识与社会建制。",
      "blocks": [
        {
          "id": "b5",
          "type": "diagram",
          "intent": "展示驿站/边塞/科举制度如何催生长亭/大漠/孤舟等意象群(使用 circular-grid)",
          "size": "l"
        },
        {
          "id": "b6",
          "type": "callout",
          "intent": "反思：玉门关并非所有诗人都去过，它如何成为边塞的集体无意识符号？",
          "size": "s"
        }
      ]
    },
    {
      "id": "evolution",
      "kind": "content",
      "eyebrow": "流变与比较",
      "headline": "时代气运与意象底色的流变",
      "lead": "同一意象在不同时代与诗人笔下，折射出迥异的心理图景。",
      "notes": "盛唐的月是空灵清远的，晚唐的月是凄迷绝望的。同样是秋天，王维空灵，杜牧清丽，李商隐绝望。意象的含义绝非固定，时代心理的衰变会改变意象的底色。用数据可视化呈现这种情感降维，比纯文字更有冲击力。",
      "blocks": [
        {
          "id": "b7",
          "type": "compare",
          "intent": "对比盛唐(王维'明月松间照')与晚唐(李商隐'沧海月明珠有泪')的'月'之意象",
          "size": "l"
        },
        {
          "id": "b8",
          "type": "chart",
          "intent": "展示初唐到晚唐'落花''流水'意象的情感降维趋势(从宏大到内敛的折线图)",
          "size": "m"
        }
      ]
    },
    {
      "id": "personal",
      "kind": "content",
      "eyebrow": "共情与创作",
      "headline": "公共意象与个人化意象",
      "lead": "伟大诗人既能调用公共意象，更能创造只属于自己的奇诡意象。",
      "notes": "折柳是公共意象，套路化但有效；李贺的鬼雨则是极度个人化的意象，无法被轻易复制。个人意象是诗人精神病理或极端体验的物化。讲透这一点，学生才能理解为何李贺被称为'诗鬼'，而非仅仅是用词怪异。",
      "blocks": [
        {
          "id": "b9",
          "type": "list",
          "intent": "列举李贺的奇诡个人意象(如'鬼雨''恨血')与李白的夸张个人意象(如'白发三千丈')",
          "size": "m"
        },
        {
          "id": "b10",
          "type": "pullquote",
          "intent": "引李贺'秋坟鬼唱鲍家诗，恨血千年土中碧'展示个人意象的穿透力",
          "size": "s"
        }
      ]
    },
    {
      "id": "empathy",
      "kind": "content",
      "eyebrow": "留白与解码",
      "headline": "留白艺术与现代解码",
      "lead": "意象的未完成性，召唤着千年后读者的情感补全。",
      "notes": "意象是情感的容器。现代人没有经历过战乱，但孤独、离别、衰老的体验是共通的。意象的留白让我们把自己的生命体验注入其中，完成二次创作。通过交互让学生亲手组合意象，感受不同组合带来的情感张力变化。",
      "blocks": [
        {
          "id": "b11",
          "type": "sim",
          "engine": "widget",
          "intent": "交互：拖拽不同意象(明月/孤舟/落花/长亭)组合，观察生成的意境色彩与情感倾向变化",
          "size": "l"
        },
        {
          "id": "b12",
          "type": "callout",
          "intent": "反思：现代人未历贬谪，为何仍能被'孤舟蓑笠翁'触动？",
          "size": "s"
        }
      ]
    },
    {
      "id": "ending",
      "kind": "hero",
      "notes": "收尾呼应：意象不是古人的密码本，而是今人的共鸣腔。当我们用自己的生命经验点亮这些物色时，唐诗才真正活在了当下。",
      "blocks": [
        {
          "id": "b_ending",
          "type": "hero",
          "intent": "收尾：意象是通往唐诗内心世界的密钥",
          "size": "xl"
        }
      ]
    }
  ]
}
